//! Exact vendor codeword assignments for the eight staged VLC trees,
//! plus all six symbol → `(run, |level|)` companion maps.
//!
//! ## Source
//!
//! Transcribed from the staged CSVs under `docs/audio/wma/tables/`
//! (`wma-huffman-*-codelen.csv`, `wma-runlevel-*.csv`, each with a
//! `.meta` provenance file). Per `docs/audio/wma/tables/README.md`
//! §"The eight VLC tables — exact vendor codewords", the vendor
//! module stores each VLC as a pre-built decode trie; the staged
//! extraction walks that trie and emits, per symbol, the **exact
//! vendor `(length, code)` assignment** — *not* a canonical
//! reconstruction. All eight tables satisfy the Kraft equality
//! exactly (complete prefix codes), including the class-2 primary
//! tree at its full 1336-symbol alphabet and the class-2 alt tree
//! (1072 symbols) — both of which supersede the earlier partial
//! flat-scan reading carried in [`crate::wire_tables`].
//!
//! A cross-check in this module's tests measures the staged
//! assignment against the canonical MSB-first `(length, symbol)`
//! reconstruction: **no table is canonical** (the scale tree is the
//! closest at 105 of 121 symbols differing), which is why decoding
//! vendor bitstreams requires these explicit codes rather than
//! [`crate::huffman::HuffmanCode::from_lengths`].
//!
//! ## Symbol roles (frame-bit-layout.md §4)
//!
//! For the six coefficient tables: symbol **0 = escape**, symbol
//! **1 = end-of-block**, and symbols `>= 2` map through the 2-based
//! companion tables (`run = RUN[s − 2]`, `|level| = LEVEL[s − 2]`);
//! the sign is a separate trailing bit. For the scale tree the delta
//! is `symbol − 60` (§3); for the gain tree `symbol − 18` (§2.1).
//!
//! Entries are `(length_in_bits, codeword)`; codewords read MSB
//! first in stream order per the staged bit-reader trace.

